export class Classic{getBegin(){return`<div class="dyjsform_entity">`}getEnd(){return`</div>`}getForm(selector){const outputName=selector.replace("#","");return`\n            <div class="dyjsform_container"></div>\n            <div class="dyjsform_footer">\n                <button type="button" class="btn btn-primary dyjsform_action_add">\n                        <i class="fas fa-plus"></i> Ajouter\n                    </button>\n                </div>\n                <textarea hidden name="${outputName}[output]"\n                       class="output"></textarea>\n            `}getField(field,rowIndex){const type=field.type?`type="${field.type}"`:"";const value=field.htmlElement!=="textarea"&&field.value?`value="${this._escapeHtml(field.value)}"`:"";let content="";const className=field.className?`${field.className}`:"";const attr=field.attr?`${field.attr}`:"";const name=!field.name.startsWith("dyjsform_action_")?`name="dyjsform[${field.name}_${rowIndex}]"`:"";const flex=field.flex||1;if(field.htmlElement==="select"&&field.options){content+=`<option></option>`;field.options.forEach((option=>{let selected=field.value===option.value?"selected":"";content+=`<option ${selected} value="${option.value}">${option.name}</option>`}))}else if(field.htmlElement==="textarea"){content=field.value?`${this._escapeHtml(field.value)}`:""}else{content=field.content?`${field.content}`:""}return`<div class="form-group" style="flex: ${flex}">\n                <div class="dyjsform_label">${field.label===""?"&nbsp;":field.label}</div>\n                <div class="dyjsform_input_container">\n                    <${field.htmlElement} ${name} class="form-control dyjsform_input ${field.name} ${className}" \n                        ${attr} ${type} ${value} data-row="${rowIndex}" data-name="${field.name}">${content}</${field.htmlElement}>\n                <span class="text-danger djf_error">${field.error}</span>\n            </div>\n        </div>`}getCss(){return`\n            .dyjsform_container {\n                display: flex;\n                flex-direction: column;\n                gap: 1rem;\n            }\n            \n            .dyjsform_entity {\n                display: flex;\n                flex-wrap: wrap;\n                gap: 1rem;\n                align-items: flex-start;\n                width: 100%;\n                padding: 1rem;\n                border-bottom: 1px solid #dee2e6;\n            }\n            \n            .dyjsform_field {\n                min-width: 200px;\n            }\n            \n            .dyjsform_label {\n                margin-bottom: 0.5rem;\n            }\n            \n            .dyjsform_input_container {\n                width: 100%;\n            }\n            \n            .dyjsform_input {\n                width: 100%;\n                margin-bottom: 0.5rem;\n            }\n            \n            .dyjsform_footer {\n                display: flex;\n                justify-content: flex-end;\n                margin-top: 1rem;\n            }\n            \n            .djf_error {\n                display: block;\n                font-size: 0.875rem;\n            }\n        `}_escapeHtml(str){return str.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}}